-- Банк ідей розвитку: що додати в пульт і в бізнес, з ефектом, зусиллям і ціною.
create table if not exists public.ideas (
  id uuid primary key default gen_random_uuid(),
  area text not null,
  phase text not null default 'now' check (phase in ('now','launch','grow')),
  title text not null,
  why text,
  catch text,
  impact smallint not null default 2 check (impact between 1 and 3),
  effort smallint not null default 2 check (effort between 1 and 3),
  cost text,
  status text not null default 'new' check (status in ('new','want','doing','done','skip')),
  top smallint,
  note text,
  task_id uuid references public.tasks(id) on delete set null,
  sort int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists ideas_area_idx on public.ideas(area);
create trigger ideas_touch before update on public.ideas
  for each row execute function public.touch_updated_at();
alter table public.ideas enable row level security;
create policy "members all" on public.ideas for all to authenticated
  using ((select public.is_member())) with check ((select public.is_member()));

