insert into public.ideas (area, phase, title, why, catch, impact, effort, cost, status, top, sort) values
('daily','now','Кнопка «Застряг» на кожній задачі','Тиснеш, коли не розумієш, що робити: задача розкладається на 3 дрібніші кроки з прикладом, а питання йде аналітику, і відповідь з''являється в навігаторі наступного ранку.','Якщо тиснути замість того, щоб пробувати, темп впаде. Тому спершу показується готова підказка, а питання вже потім.',3,1,'0 грн','new',10,1),
('daily','now','Режим «маю 15 / 30 / 60 хвилин»','Обираєш, скільки маєш часу сьогодні, і навігатор підбирає задачі, що в нього влазять. Прибирає головну пастку новачка: відкрив план, злякався обсягу, закрив.','Працює, тільки якщо оцінки часу в задачах чесні. Після кожної виконаної задачі варто питати «скільки реально пішло».',3,1,'0 грн','new',null,2),
('daily','now','Telegram-бот: одне повідомлення на день','О 9:00 три задачі на сьогодні і найближчий дедлайн. Кнопка «Зроблено» прямо в Telegram відмічає задачу в пульті. Не треба пам''ятати відкривати сайт.','Більше одного повідомлення на день перетворюється на шум, який вимикають. Тільки ранок плюс термінові тривоги.',3,2,'0 грн','new',6,3),
('daily','now','Тижневий підсумок щонеділі','Що зроблено, скільки витрачено, на скільки днів відстаєш від плану і що головне на наступний тиждень. Видно прогрес, навіть коли продажів ще нема.',null,2,1,'0 грн','new',null,4),
('daily','now','Один головний показник на кожен етап','До запуску головне число на головній — «днів до першого продажу», після запуску — «прибуток за тиждень». Решта цифр дрібніше.',null,2,1,'0 грн','new',null,5),
('daily','now','Журнал рішень з датою перевірки','Кожне велике рішення (беру товар, відмовляюсь, міняю ціну) записується з причиною. Через місяць пульт питає: «чи було це правильно?». Так ростеш швидше, ніж на чужих порадах.','Потрібно 10 секунд дисципліни на кожне рішення. Можна записувати автоматично при «Беру в тест» і «Відхилити».',2,1,'0 грн','new',null,6),
('daily','now','Єдиний календар дедлайнів','Податки, «замовити до» для сезонних товарів, кінець тесту товару, акції банків і НП — на одній стрічці по датах.',null,2,1,'0 грн','new',null,7),
('daily','now','Кнопка «+» для швидкого запису з телефона','Одне поле внизу екрана: задача, ідея товару, витрата або нотатка. Пульт сам вгадує тип за словами («витратив 300 на зразки» → витрата).',null,2,1,'0 грн','new',null,8),
('daily','now','Пошук по всьому пульту','Один рядок шукає по товарах, задачах, готових текстах, джерелах і гайдах. Чим більше даних, тим важливіше.',null,2,2,'0 грн','new',null,9),
('daily','now','Перевірка реальності плану раз на тиждень','Аналітик дивиться, скільки задач прострочено, і чесно пише: «з таким темпом перший продаж буде не в листопаді, а в січні — ось що прибрати з плану».',null,2,1,'0 грн','new',null,10),
('daily','launch','Голосові нотатки','Надиктовуєш думку, аналітик розкладає її в задачі або нотатки до товару.','Розпізнавання української в браузері нестабільне. Простіше надиктовувати в Telegram-бот.',1,2,'0 грн','new',null,11),
('product','now','Тест попиту до закупки','Оголошення на OLX або Prom «під замовлення» з фото зразка: за 7 днів рахуємо перегляди, збереження й повідомлення. Якщо ніхто не пише — гроші на партію не витрачаєш.','Тільки чесно: писати, що товар очікується, і не брати передоплату. Чужі фото — лише до приходу своїх зразків.',3,1,'0–100 грн','new',1,12),
('product','now','Автофільтр «це не для мене»','Банк товарів сам ховає те, що не пасує моделі: крихке, електроніка з гарантією, косметика і дитяче (потрібна сертифікація), бренди (підробки), вага понад 1 кг, ціна до 300 грн.','Фільтр має пояснювати, чому товар сховано, інакше можна втратити хороший варіант через одну помилкову мітку.',3,1,'0 грн','new',2,13),
('product','now','Скільки реально продають конкуренти','Щотижневий знімок лічильників «куплено N разів» і кількості відгуків у конкурентів на Prom. Приріст за тиждень — найкращий доказ попиту, кращий за Google Trends.','Лічильники є не в усіх; відгуки — це лише 2–5% продажів, тож множити треба обережно.',3,2,'0 грн','new',8,14),
('product','now','Аналіз поганих відгуків конкурентів','Аналітик збирає відгуки на 1–2 зірки і пише: на що скаржаться (ламається, немає інструкції, не той розмір). Це готовий список, як зробити свій товар або опис кращим.',null,3,2,'0 грн','new',null,15),
('product','now','Сезонний календар на 12 місяців','Що і коли продається в Україні (школа, Новий рік, дача, 8 березня, Чорна п''ятниця) з датою «замовляти до» з урахуванням 45–55 днів доставки з Китаю.','Найпоширеніша помилка — привезти сезонний товар в останній тиждень сезону. Календар має бути жорстким: після дати замовлення товар сірий.',3,1,'0 грн','new',5,16),
('product','now','Розклад оцінки товару по складниках','Замість однієї цифри — смужки: попит, маржа, конкуренція, ризик, сезонність. І підказка, що треба перевірити, щоб оцінка виросла.',null,2,1,'0 грн','new',null,17),
('product','now','Порівняння 2–3 товарів поруч','Обираєш кілька товарів з банку — бачиш таблицю бік-о-бік: ціна, маржа, вага, конкуренти, сезон, ризики.',null,2,1,'0 грн','new',null,18),
('product','now','Комплекти замість одного товару','Аналітик шукає пари, які купують разом (органайзер + наклейки, форма + лопатка). Вищий чек, а головне — немає ідентичного лоту, з яким воювати ціною.','Комплект ускладнює закупку і склад. Починати з 2 позицій від одного постачальника.',3,1,'0 грн','new',null,19),
('product','now','Причина відмови для кожного товару','Коли відхиляєш товар, пишеш одну фразу чому. Аналітик більше не пропонує схожі, а через пів року видно, які причини повторюються.',null,2,1,'0 грн','new',null,20),
('product','now','Перевірка торговельних марок','Перед тестом — пошук назви і дизайну в базі торговельних марок. Rozetka і Prom знімають підробки, а партія залишається на складі.',null,2,1,'0 грн','new',null,21),
('product','now','Ідеї з підказок пошуку Prom','Що люди вводять у пошук (автодоповнення) — безкоштовне джерело попиту. Аналітик раз на тиждень збирає нові запити у твоїх нішах.',null,2,2,'0 грн','new',null,22),
('product','now','Google Trends у картці товару','Графік інтересу в Україні за 12 місяців прямо в картці: видно сезонний пік і чи тренд росте.','Для вузьких товарів даних замало, графік буде шумом. Показувати тільки, коли є сигнал.',2,2,'0 грн','new',null,23),
('product','launch','Тривога: конкурент зник або підняв ціну','Якщо в головного конкурента закінчився товар або виросла ціна — це момент підняти свою ціну чи рекламу.','Маркетплейси не люблять автоматичний збір. Робити рідко (раз на добу) і лише по 5–10 конкурентах.',2,3,'0 грн','new',null,24),
('supply','now','Готові листи постачальнику англійською і китайською','Запит ціни і MOQ, прохання зразків, торг, запит відео упаковки, претензія за брак. Копіюєш одним тапом, як готові тексти для покупців.',null,3,1,'0 грн','new',4,25),
('supply','now','Чекліст перед замовленням партії','Кнопка «Замовити партію» відкривається тільки після 12 галочок: зразок перевірено, маржа від 30%, тест попиту пройдено, вага з упаковкою, сертифікати не потрібні, гроші на рекламу відкладено.','Перша партія — найдорожча помилка новачка. Тут краще бути занудою.',3,1,'0 грн','new',7,26),
('supply','now','Реальна ціна на складі в Україні по кожній пропозиції','Пропозиції постачальників показують не ціну на 1688, а повну: товар + доставка по Китаю + карго за вагою + упаковка. Інколи «дешевший» постачальник виявляється дорожчим.',null,3,1,'0 грн','new',null,27),
('supply','now','Оцінка постачальника за чеклістом','Років на 1688, відповідає до доби, дав відео, зразок відповідає фото, погоджується на свою упаковку. Сумарний бал поруч із назвою.',null,2,1,'0 грн','new',null,28),
('supply','now','Бюджет партії: скільки штук і скільки на рекламу','Вводиш, скільки маєш грошей, — пульт рахує, скільки штук замовити з урахуванням MOQ і скільки обов''язково лишити на рекламу та запас.','Найчастіше гроші закінчуються на рекламі, а не на товарі. Резерв на рекламу має бути обов''язковим.',3,1,'0 грн','new',null,29),
('supply','launch','Трекер партії від Китаю до складу','Статуси: оплачено → склад у Китаї → в дорозі → митниця → фулфілмент НП, з датою прибуття, що оновлюється. Видно, коли починати рекламу.',null,3,2,'0 грн','new',null,30),
('supply','now','Карго: авіа, авто чи море','Калькулятор показує ціну і термін для кожного варіанту з урахуванням щільності товару (легкий і об''ємний дешевше везти інакше).',null,2,1,'0 грн','new',null,31),
('supply','now','Порівняння карго-компаній','Таблиця 4–5 «білих» перевізників: ціна за кг, термін, чи дають документи для ФОП, страхування, відгуки. Аналітик оновлює раз на місяць.',null,2,1,'0 грн','new',null,32),
('supply','now','Перевірка якості перед відправкою','Що просити в постачальника до оплати решти: фото коробок, відео з випадковою одиницею, вага, маркування.',null,2,1,'0 грн','new',null,33),
('supply','launch','Коли замовляти наступну партію','Продажі за день × днів доставки + запас = точка дозамовлення. Пульт пише «пора замовляти» до того, як товар закінчиться і ти втратиш позиції в пошуку.',null,3,1,'0 грн','new',null,34),
('supply','launch','Своя вкладка і наліпка на упаковці','Картка з подякою, QR на відгук і знижкою на наступну покупку. Дешево, піднімає відгуки й повторні продажі.',null,2,1,'від 300 грн','new',null,35),
('supply','grow','Штрихкоди EAN для Rozetka','Як отримати свої штрихкоди і коли вони обов''язкові. Без них не вийти на Rozetka і деякі фулфілменти.','Це щорічна плата. Не робити до того, як товар довів, що продається.',2,1,'щорічний внесок','new',null,36),
('price','now','«Що буде, якщо…» для кожного товару','Повзунки: курс +10%, реклама вдвічі дорожча, відмови 25%, ціна −10%. Одразу видно, чи товар витримує поганий сценарій.','Якщо маржа зникає вже при одному поганому повзунку — товар надто крихкий для першого тесту.',3,1,'0 грн','new',null,37),
('price','now','Тривога при стрибку курсу','Курс НБУ вже тягнеться автоматично. Якщо він зріс більш ніж на 3% — пульт перераховує всі товари і пропонує нові ціни.',null,2,1,'0 грн','new',null,38),
('price','now','Ціна за кількість: 1 / 2 / 3 штуки','Знижка на другу і третю одиницю піднімає середній чек, а доставка та реклама ті самі. Пульт рахує, яка знижка ще в плюсі.',null,3,1,'0 грн','new',null,39),
('price','now','Мінімальна ціна великими цифрами','Ціна, нижче якої кожен продаж — збиток. Щоб у торгах із клієнтом або в акції не піти в мінус.',null,2,1,'0 грн','new',null,40),
('price','now','Попередження «дорожче за ринок»','Правило з плану: ціна не вище медіани конкурентів. Якщо так — товар підсвічується, а аналітик пише, чим виправдати різницю.',null,2,1,'0 грн','new',null,41),
('price','launch','Справжня собівартість після приходу партії','Фактичні витрати (товар, карго, мито, комісії, брак) розносяться на кожну штуку і порівнюються з планом. Так калькулятор вчиться бути точнішим.',null,3,2,'0 грн','new',null,42),
('sell','now','Картка товару окремо під Prom, OLX і Rozetka','У кожного майданчика свої ліміти назви і правила. Аналітик пише назву з ключовими словами, опис, характеристики і FAQ під кожен окремо.',null,3,2,'0 грн','new',null,43),
('sell','now','Чекліст якості картки','8+ фото, перше на білому, розміри на фото, відео, 5 переваг, відповіді на типові питання, ключові слова в назві. Бал картки від 0 до 100.',null,2,1,'0 грн','new',null,44),
('sell','now','Слова, якими шукають покупці','Збір пошукових запитів по товару з Prom і Google, щоб назва і опис збігались із тим, що люди реально вводять.',null,3,2,'0 грн','new',null,45),
('sell','now','Інфографіка і фон для фото','Перше фото з білим фоном і 3 перевагами текстом сильно впливає на кліки. Шаблон і безкоштовне видалення фону.',null,3,2,'0–300 грн','new',null,46),
('sell','now','Фотостудія вдома за 300 грн','Лайтбокс, білий фон, телефон, денне світло: покроковий гайд і 8 обов''язкових ракурсів.',null,2,1,'≈300 грн','new',null,47),
('sell','now','Відео постачальника як старт','Китайські постачальники зазвичай дозволяють використовувати їхні відео. Можна стартувати з ними, поки нема своїх.','Ті самі відео вже в інших продавців, тож це тимчасово. Свої відео руками все одно потрібні.',2,1,'0 грн','new',null,48),
('sell','launch','Prom: замовлення в пульт автоматично','Через API Prom нові замовлення самі з''являються в «Замовленнях», а статуси повертаються назад. Без ручного переписування.',null,3,3,'0 грн','new',null,49),
('sell','launch','OLX: оголошення і повідомлення в пульті','Через API OLX бачити перегляди, повідомлення й оновлювати оголошення з пульта.','Доступ до API OLX дають не всім одразу; може знадобитися заявка.',2,3,'0 грн','new',null,50),
('sell','grow','Rozetka Seller: синхронізація','Товари, залишки і замовлення Rozetka в пульті. Тільки після того, як буде 20+ відгуків на Prom.',null,2,3,'0 грн','new',null,51),
('sell','launch','Лендинг на товар на цьому ж сайті','Сторінка з фото, ціною і кнопкою «Написати в Telegram/Viber» — для реклами в Instagram і TikTok. Хостинг безкоштовний на тому ж Vercel.','Без відгуків лендинг продає гірше за Prom. Запускати, коли вже є що показати.',3,2,'≈400 грн/рік за домен','new',null,52),
('sell','launch','Каталог у Telegram-каналі з ботом','Канал із товарами, бот приймає замовлення (ім''я, місто, відділення) і кладе їх у пульт.',null,2,2,'0 грн','new',null,53),
('sell','launch','Прохання про відгук через 3 дні після отримання','Коли НП показує «отримано», пульт через 3 дні нагадує надіслати покупцю шаблон з посиланням на відгук. Перші 10 відгуків вирішують усе.',null,3,2,'0 грн','new',null,54),
('sell','launch','Монітор рейтингу продавця','Рейтинг на Prom, швидкість і відсоток відповідей. Якщо падає — тривога, бо падає й позиція в пошуку.',null,2,2,'0 грн','new',null,55),
('sell','launch','Безкоштовні канали під товар','Список тематичних груп і дошок під конкретний товар (дачники, мами, авто) з правилами, де можна публікувати.','За спам банять. Тільки там, де реклама дозволена правилами групи.',2,1,'0 грн','new',null,56),
('sell','grow','Повторні продажі покупцям','Через 30–60 днів — повідомлення тим, хто дав згоду: новий товар або знижка. Повторний покупець коштує в рази дешевше за нового.',null,2,2,'0 грн','new',null,57),
('sell','launch','Розпродаж залежаних залишків','Товар не продається 30 днів → пульт пропонує план: комплект, знижка, OLX, акція. Гроші в залишках — заморожені гроші.',null,2,1,'0 грн','new',null,58),
('chat','launch','Одна скринька для всіх чатів','Prom, OLX, Telegram і Instagram в одному місці в пульті. Таблиця повідомлень у базі вже є, треба під''єднати канали.','Instagram потребує верифікації Meta Business. Почати з Telegram і Prom.',3,3,'0 грн','new',null,59),
